export const syntaxExamples = [
  {
    "name": "case-when",
    "title": "Conditional values with case (relabel codes / bucket a measure)",
    "summary": "`case when <cond> then <val> ... else <val> end` to relabel codes or bucket a measure into a derived value, then group by it",
    "body": "# `case when <cond> then <val> ... else <val> end` builds a derived value.\n# Assign it to an `auto` concept, then group/filter by it like any other.\n# Use `else null` when unmatched rows should drop out of downstream grouping.\nimport iris as iris;\n\nauto petal_size <- case\n    when iris.petal_length < 2.0 then 'small'\n    when iris.petal_length < 5.0 then 'medium'\n    else 'large'\nend;\n\nselect\n    petal_size,\n    count(iris.petal_length) as flower_count,\n    avg(iris.petal_width) as avg_petal_width,\norder by flower_count desc;\n"
  },
  {
    "name": "chart",
    "title": "Chart statement - layers, roles, settings and reference lines",
    "summary": "drawing a result rather than tabulating it: `chart layer <type> ( <role> <- <expr> as <name>, ... )` is a STATEMENT that wraps its own query - the bindings ARE the select; layers, roles, scales, reference lines and `from <select>`",
    "body": "# `chart` is a top-level statement, like `select` - it wraps a query AND says\n# how to draw it. It renders wherever results render: a trilogy code block in a\n# `trilogy render` report, a studio cell, terminal output, and\n# `copy into png|svg|html|pdf '<path>' from chart ...` for a standalone image.\nimport enrollments as enroll;\n\n# --- 1. Minimal form --------------------------------------------------------\n# `layer <type> ( <role> <- <expr> [as <name>], ... )`. The bindings ARE the\n# select: grouping is automatic by the non-aggregated ones, exactly as in a\n# query. NEVER write a separate `select` for a chart.\nchart layer bar ( x_axis <- enroll.department, y_axis <- sum(enroll.credits) as credits );\n\n# A COMPUTED binding must be aliased: `y_axis <- sum(enroll.credits) as credits`.\n# A bare concept reference needs no alias (`x_axis <- enroll.department`) but may\n# take one as a display label. `y_axis <- sum(...)` with no `as` is a parse error.\n#\n# GRAIN: every binding is a select column, so binding a FINER concept to any\n# role (color, group, annotation, ...) refines the grain and splits the marks -\n# exactly as adding that column to a select would. Aggregate annotations at the\n# mark's own grain (`count(enroll.id) as ...`) instead of binding a detail field.\n\n# --- 2. Every part of the statement -----------------------------------------\n# Components may appear in any order after `chart`; at least one `layer` is\n# required, and multiple `layer`s compose into one overlaid chart.\nchart\n  set show_title                            # title from the value-axis label\n  set hide_legend\n  set scale_y: log                          # scale_x | scale_y : linear | log | sqrt\n  layer bar (\n    x_axis <- enroll.department,\n    y_axis <- sum(enroll.credits) as credits,\n    color <- enroll.completed,              # one legend series per value\n    annotation <- count(enroll.id) as enrollments   # text label on each mark\n  )\n  order by credits desc                     # category order follows ORDER BY\n  limit 10                                  # (ascending when there is no ORDER BY)\n  place hline at 5 as target;               # reference rule; `place vline at ...`\n                                            # too. `at` takes a literal; `as <label>`\n                                            # is optional\n\n# --- 3. `from <select>` - when the bindings cannot express the query ---------\n# Bindings alone have no `where` / `having` / hidden columns. Add `from` plus a\n# COMPLETE select, which carries its own clauses in the usual order:\nchart layer line (\n    x_axis <- enroll.year,\n    y_axis <- completions,\n    color <- enroll.department\n  )\n  from\n  where enroll.year >= 2016\n  select\n    enroll.year,\n    enroll.department,\n    count(enroll.id ? enroll.completed = true) as completions\n  order by enroll.year asc;\n# With `from select`, EVERY binding must be a bare reference to one of the\n# select's outputs - put transformations inside the select - and layer-level\n# `order by` / `limit` are rejected: they belong to the select.\n\n# --- 4. Types ---------------------------------------------------------------\n#   bar       vertical bars: x_axis = category, y_axis = measure\n#   barh      horizontal bars: x_axis = MEASURE, y_axis = category (roles swap)\n#   line      x_axis = the ordered axis (date/year), y_axis = measure\n#   point     scatter; `size <- <measure>` scales the marks\n#   area      line, filled\n#   headline  big KPI number - needs only `x_axis <- <measure> as <name>`\n#   donut     the numeric binding sizes the slices; the other positional one -\n#             or `color` - names them. No annotations.\n#   heatmap   x_axis and y_axis are BOTH categories, `color` is the measure\n#   boxplot   x_axis = category, y_axis = the distribution being summarized\n# `treemap` parses but no renderer implements it; the error names what does.\nchart layer barh ( x_axis <- sum(enroll.credits) as credits, y_axis <- enroll.department );\nchart layer headline ( x_axis <- count(enroll.student_id) as students );\nchart layer donut ( x_axis <- enroll.department, y_axis <- sum(enroll.credits) as credits );\nchart layer heatmap (\n    x_axis <- enroll.year,\n    y_axis <- enroll.department,\n    color <- sum(enroll.credits) as credits\n);\n# A boxplot summarizes RAW rows, so its select has to carry the fact's row grain\n# - hidden with `--` - or output dedup collapses the distribution to the set of\n# distinct values.\nchart layer boxplot ( x_axis <- enroll.department, y_axis <- enroll.credits )\n  from select --enroll.id, enroll.department, enroll.credits;\n\n# --- 5. Roles ---------------------------------------------------------------\n#   x_axis, y_axis          position\n#   color                   one series per value, WITH a legend\n#   size                    mark size (point)\n#   group                   side-by-side bars, or a per-series split on\n#                           line/point/area - no legend\n#   x_trellis / y_trellis   small multiples (columns / rows)\n#   annotation              per-mark text label\n#   geo                     reserved - parses, then raises\n# Each role may be bound at most once per layer; an unknown role name is a parse\n# error. Trellis roles cannot combine with multiple layers, placements, or\n# annotations (Vega-Lite forbids facets inside layered charts).\nchart layer bar (\n    x_axis <- enroll.year,\n    y_axis <- sum(enroll.credits) as credits,\n    group <- enroll.department              # side-by-side bars, no legend\n);\n\n# EXPLICIT SERIES COLORS: select a `string::hex` column (the trait comes from\n# `import std.color;`) alongside a `color` binding and each color value takes the\n# hex code found on its rows (missing -> gray); bind the hex column itself to\n# `color` to use the codes directly.\n"
  },
  {
    "name": "correlated-exists-via-grouped-counts",
    "title": "Correlated EXISTS / NOT-EXISTS over rows of the SAME model",
    "summary": "translate `EXISTS other` / `NOT EXISTS other matching` over the same model into two `count(...) by <grain>` compared in `where` (`> 1` = another exists, `= 1` = no other matches) - pin the correlation grain with `by`",
    "body": "# A self-referential EXISTS / NOT-EXISTS (e.g. \"the ONLY enrollee who completed\n# a course that had more than one enrollee\") becomes TWO filtered counts pinned\n# to the correlation grain, compared in `where`:\n#   count(k) by <grain> > 1            # EXISTS another row in the group\n#   count(k ? cond) by <grain> = 1     # NOT EXISTS another row matching cond\n#                                         (exactly one matches: the row itself)\n# An aggregate condition in `where` groups by the SELECT grain unless pinned.\n# When the correlation grain DIFFERS from the select grain - as here\n# (correlate by course, select per student) - you MUST pin it with `by <grain>`;\n# a bare `count(...) > 0` would group by the select grain and give wrong rows.\n# SCOPE: the pin fixes only the GROUPS. A `where` aggregate always computes\n# over ALL rows of the model; the other `where` predicates never narrow its\n# input rows - exactly right for whole-table EXISTS checks like this one. If\n# the aggregate should see only already-filtered rows, use `having` or stage\n# it with `then where` (a stage's aggregates see only rows passing earlier\n# stages).\nimport enrollments as enroll;\n\nauto enrollees_per_course <- count(enroll.student_id) by enroll.course;\nauto completers_per_course <- count(enroll.student_id ? enroll.completed = true) by enroll.course;\n\nwhere\n    enroll.completed = true\n    and enrollees_per_course > 1     # the course had at least one OTHER enrollee\n    and completers_per_course = 1    # and no OTHER enrollee completed it\nselect\n    enroll.student_id,\n    count(enroll.course) as sole_completions\norder by sole_completions desc\nlimit 100;\n"
  },
  {
    "name": "dedup-before-aggregate",
    "title": "Deduplicate identical rows before aggregating (UNION DISTINCT)",
    "summary": "a `rowset <- select <cols>` collapses identical tuples to one row (SELECT-grain group by) before a downstream sum - the `distinct`/UNION substitute",
    "body": "# `distinct` and UNION are not available. To collapse identical tuples to one\n# row BEFORE aggregating (so duplicates don't double-count), materialize the\n# tuple in a `rowset <- select <cols>`: a rowset select groups at its own grain,\n# emitting one row per distinct tuple. Then aggregate over the rowset's columns.\n#  - ALIAS every rowset column you reference downstream with `as`. Without `as`,\n#    the column keeps its FULL source path under the rowset name - `select\n#    sales.item.brand_id` is reachable as `rs.sales.item.brand_id`, NOT\n#    `rs.brand_id`. `as brand_id` makes it `rs.brand_id`.\nimport enrollments as enroll;\n\n# Collapse repeat (student, course) enrollments to one row each (a student who\n# took a course in multiple years counts once).\nrowset unique_sc <- select\n    enroll.student_id as sid,\n    enroll.course as course,\n;\n\n# Count over the deduplicated rows - identical (student, course) pairs counted once.\nselect\n    unique_sc.course,\n    count(unique_sc.sid) as distinct_students,\norder by unique_sc.course asc;\n"
  },
  {
    "name": "except-intersect-setops",
    "title": "Set difference / co-occurrence across sources with except(...) / intersect(...)",
    "summary": "set difference or co-occurrence across sources",
    "body": "# `except(...)` and `intersect(...)` are relational table-valued functions with the\n# SAME shape as `union(...)`: TWO OR MORE inline self-contained select arms, matched\n# by COLUMN POSITION to the trailing `-> (...)` output list. They are SQL SET\n# operators, which differ from the union stack in three ways:\n#   - the output is DEDUPLICATED (distinct rows);\n#   - whole rows are compared with NULL-SAFE equality (NULL matches NULL - the\n#     same identity semantics as `in` / `not in` membership);\n#   - for `except(...)` ARM ORDER MATTERS: the FIRST arm is the base population and\n#     every later arm is subtracted from it, left to right.\n# Use `except` for \"combinations in A that never appear in B (or C)\" and\n# `intersect` for \"combinations present in every source\".\nimport enrollments as enroll;\n\n# Distinct (course, year) combinations Biology offered that Chemistry did not.\nwith bio_only as except(\n    (where enroll.department = 'Biology'\n     select enroll.course as course, enroll.year as year),\n    (where enroll.department = 'Chemistry'\n     select enroll.course as course, enroll.year as year)\n) -> (course, year);\n\nselect\n    bio_only.course,\n    bio_only.year,\norder by bio_only.course asc nulls first, bio_only.year asc nulls first\nlimit 100;\n\n# Counting the surviving combinations is the idiomatic anti-membership count\n# (e.g. \"customers who bought in store but never online\"):\n#     from except((...store combos...), (...web combos...)) -> (last, first, day)\n#     select count(day) as combos;\n# ---------------------------------------------------------------------------\n# NOTES:\n#  - Same arm rules as `union(...)`: inline arms only, positional binding, equal\n#    column count/order/types per arm; reference outputs as `<rowset>.<output>`.\n#  - `except((a), (b), (c))` means (a EXCEPT b) EXCEPT c - subtract left to right.\n#    `intersect(...)` keeps rows present in EVERY arm (order does not matter).\n#  - Outputs are DISTINCT rows: aggregate them directly (`count(x)`) for \"how many\n#    unique combinations\" - no extra dedup step needed.\n"
  },
  {
    "name": "existence-anti-join",
    "title": "Existence / anti-join across models",
    "summary": "keeping or excluding rows by whether a key matches another model",
    "body": "# `in` / `not in` against another model's key is the semi-join / anti-join\n# idiom - no manual JOIN. Use it instead of `count(...) is null` hacks.\n# Membership is IDENTITY matching and total: NULL matches NULL, the result is\n# never NULL, and `not in` is the EXACT complement of `in` - a NULL in the set\n# does not empty an anti-join (no SQL NOT-IN footgun), and NULL-keyed rows land\n# in exactly one of the two sides. For strict SQL parity, filter NULLs\n# explicitly (`where key is not null and key in other.key`).\nimport students as students;\nimport enrollments as enroll;\n\n# semi-join: majors with at least one student enrolled in 'Biology 101'\nauto bio_students <- enroll.student_id ? enroll.course = 'Biology 101';\nwhere students.id in bio_students\nselect students.major, count(students.id) as enrolled_students;\n\n# anti-join: students who never enrolled in ANY course\nwhere students.id not in enroll.student_id\nselect students.major, count(students.id) as never_enrolled;\n\n# NULLABLE FLAG: a flag that is true only when a match exists and NULL otherwise\n# (e.g. `enroll.completed` set only for graded rows) needs `is null` for the\n# \"never matched\" case - `not flag` evaluates NULL→dropped, losing those rows.\nwhere enroll.completed is null\nselect enroll.student_id;\n\n# COMPOSITE (multi-column) membership: to test a MULTI-PART key against a set,\n# wrap both sides in matching tuples - `(a, b) in (set.a, set.b)`. This matches\n# ROW-WISE (the whole tuple must appear as one row of the set), so it is NOT the\n# same as `a in set.a and b in set.b`, which matches the parts independently and\n# lets unrelated cross-pairs through. Build the set as a `rowset` selecting the\n# key columns, then test the tuple with `in` / `not in`. Prefer this over\n# concatenating the parts into a single string key.\nrowset multi_course_pairs <- select\n    enroll.department as dept,\n    enroll.course as course,\nhaving count_distinct(enroll.year) > 1;      # (dept, course) offered in >1 year\n\nwhere (enroll.department, enroll.course)\n    in (multi_course_pairs.dept, multi_course_pairs.course)\nselect enroll.student_id, count(enroll.id) as enrollments;\n"
  },
  {
    "name": "filtered-aggregate",
    "title": "Filtered aggregate - aggregate only the rows matching a condition",
    "summary": "aggregating only the rows matching a condition, and counting rows correctly",
    "body": "# `?` is a local filter - a filter that applies only to the prior expression-\n# several differently-filtered measures can share one select. Add `by <grain>`\n# to pin an aggregate to a grain other than the select's.\nimport iris as iris;\n\nselect\n    iris.species,\n    avg(iris.petal_length) as avg_petal,\n    avg(iris.petal_length ? iris.petal_width > 1.5) as avg_petal_wide_only,\n    count(iris.petal_length ? iris.sepal_length > 6.0) as long_sepal_count,\norder by iris.species asc;\n\n# COUNTING ROWS: `count(k ? cond)` counts DISTINCT values of k - `count` is\n# distinct-by-argument. To count matching ROWS, count the model's unique grain /\n# row key (often named `row_key`), NOT a non-unique sub-key. e.g. counting line\n# items by `count(line_number ? cond)` collapses to the number of distinct line\n# numbers (1..7) and undercounts - use `count(row_key ? cond)`.\n\n# COMPOSITE GRAIN: when SEVERAL keys together identify the thing you are counting,\n# name them with `grain(...)` instead of picking one:\n#   count(grain(sales.order_id, sales.item_id))                 # order+item lines\n#   count_distinct(grain(cust.first_name, cust.last_name, sales.date))\n# `grain(...)` is NEVER NULL, so a combination with a missing member (a customer\n# with no last name) still counts - whereas `count(last_name)` silently drops it.\n# It composes with `?` like any expression: count(grain(a, b) ? cond).\n"
  },
  {
    "name": "nested-aggregate-group-average",
    "title": "Compare a per-entity total to the group average of those totals",
    "summary": "the \"above 1.2x the group norm\" ask: inner `sum(x) by entity, group`, outer `avg(inner) by group`; use WHERE for the comparison when a separate output-only filter must not narrow the benchmark",
    "body": "# Compare each entity's total to the GROUP AVERAGE of those per-entity totals\n# (the \"above 1.2x the group norm\" pattern). Give EACH grain its own `by`: the\n# inner total is per (entity, group); the outer average re-aggregates those\n# totals up to the group. \n# since the aggregates are in the having, both are aggregates *after* the id filter is applied\nimport enrollments as enroll;\n\nauto student_dept_credits <- sum(enroll.credits) by enroll.student_id, enroll.department;\nauto dept_avg_credits <- avg(student_dept_credits) by enroll.department;\n\nwhere enroll.student_id > 103\nselect\n    enroll.student_id,\nhaving student_dept_credits > 1.2 * dept_avg_credits;\n\n# BENCHMARK OVER FULL POPULATION + FILTERED OUTPUT: if the department average must span\n# EVERY student but the output should contain only target students (id > 103), put the aggregate\n# comparison in WHERE alongside the output-only filter. Aggregate conditions in WHERE do\n# not filter one another's inputs, so `student_id > 103` does not narrow the department\n# benchmark. Do NOT put the comparison in HAVING after the output filter; that computes a\n# target-students-only department average.\nwhere\n    student_dept_credits > 1.2 * dept_avg_credits\n    and enroll.student_id > 103\nselect\n    enroll.student_id,\n    enroll.department,\n    student_dept_credits,\n;\n\n# SCOPED INPUT POPULATION: when the totals and their group average must use only\n# rows from a specific period, bind that condition inside the inner aggregate.\n# A separate output-only filter still belongs in the final WHERE and does not\n# narrow the rows feeding either aggregate.\nauto student_dept_credits_2024 <- sum(enroll.credits ? enroll.year = 2024)\n    by enroll.student_id, enroll.department;\nauto dept_avg_credits_2024 <- avg(student_dept_credits_2024) by enroll.department;\n\nwhere\n    student_dept_credits_2024 > 1.2 * dept_avg_credits_2024\n    and enroll.student_id > 103\nselect\n    enroll.student_id,\n    enroll.department,\n    student_dept_credits_2024,\n;\n\n# HIDDEN GROUP KEY: if the requested output is one row per (student, department)\n# but displays only student_id, keep department in the select with the `--`\n# PREFIX. Otherwise identical displayed student rows are deduplicated and the\n# required per-department row grain is lost.\nwhere student_dept_credits_2024 > 1.2 * dept_avg_credits_2024\nselect\n    enroll.student_id,\n    --enroll.department,\n;\n\n# For more complex boundaries, compute the full-population benchmark in a separate rowset\n# with no output filter, then apply the subset filter only in the final selection.\n"
  },
  {
    "name": "pivot-columns",
    "title": "Pivot dimension values into columns",
    "summary": "turn distinct values of a dimension into columns with a reusable `def` macro + filtered aggregate",
    "body": "# A `def` macro expands inline at each `@call`. Pair it with a filtered\n# aggregate to project one column per category value (a pivot). With no row\n# dimension in the select this yields a single summary row.\nimport iris as iris;\n\ndef species_avg(s) -> avg(iris.petal_length ? iris.species = s);\n\nselect\n    @species_avg('setosa') as setosa_avg_petal,\n    @species_avg('versicolor') as versicolor_avg_petal,\n    @species_avg('virginica') as virginica_avg_petal,\n;\n"
  },
  {
    "name": "python-datasource",
    "title": "Python script datasource - Arrow IPC producer plus Trilogy model",
    "summary": "run a local Python script as a datasource: wrap a function in `trilogy.io.run`, which writes the Arrow IPC stream to stdout for you from a table, dataframe, or list of dicts; declare concepts, map script columns in `datasource (...)`, use `grain (...) file `path.py`;`, then reference locally declared concepts WITHOUT the datasource name as a prefix",
    "body": "# Python datasources require `enable_python_datasources = true` under\n# `[engine.config]` in trilogy.toml. Create these TWO files side by side.\n#\n# File 1: fibonacci.py\n# ---------------------------------------------------------------------------\n# #!/usr/bin/env -S uv run\n# # /// script\n# # requires-python = \">=3.11\"\n# # dependencies = [\"pyarrow>=16\", \"pytrilogy\"]\n# # ///\n#\n# from trilogy.io import run\n#\n#\n# def fibonacci():\n#     values = [0, 1]\n#     while len(values) < 20:\n#         values.append(values[-1] + values[-2])\n#     return [{\"index\": i, \"value\": v} for i, v in enumerate(values)]\n#\n#\n# if __name__ == \"__main__\":\n#     raise SystemExit(run(fibonacci))\n#\n# `run` converts whatever you return -- a pyarrow table, a pandas/polars frame,\n# a list of dicts, or an iterator of those -- and gives the script a CLI\n# (`--limit`, `--filter`, `--columns`, `--describe`). Run\n# `trilogy source describe ./fibonacci.py` to print the datasource block below\n# instead of writing it against a guessed schema.\n#\n# IMPORTANT: stdout must contain ONLY the Arrow IPC stream. Send diagnostics\n# to stderr. A PEP 723 block lets `uv run` install script dependencies.\n#\n# File 2: query.preql\n# ---------------------------------------------------------------------------\nkey index int;\nproperty index.value int;\n\n# The left side is the physical Arrow column; the right side is the Trilogy\n# concept declared above. The file suffix identifies this as a Python source.\ndatasource fibonacci_numbers (\n    index: index,\n    value: value,\n)\ngrain (index)\nfile `./fibonacci.py`;\n\n# A datasource declaration does NOT create a namespace. Use local concepts as\n# `index` and `value`, NOT `fibonacci_numbers.index` / `.value`.\nselect\n    index,\n    value,\norder by index;\n"
  },
  {
    "name": "query-structure",
    "title": "Full query structure - every clause and where it goes (+ rowsets)",
    "summary": "the exact clause order of a query, and how to define a rowset",
    "body": "# Every Trilogy query has the SAME fixed skeleton. Top-level statements come\n# first (each ends with `;`), then ONE query whose clauses appear in this exact\n# order - each clause is OPTIONAL except `select`:\n#\n#   <top-level statements>;        # import / key / property / auto / metric /\n#                                  #   rowset / merge / def / datasource / parameter\n#   where   <row condition>        # 1. filter INPUT rows (BEFORE aggregation)\n#   select  <col>, <agg> as name,  # 2. the projection - grouping is AUTOMATIC by the\n#                                  #      non-aggregated columns (never write GROUP BY)\n#   <subset|union join a = b (=c)?>* # 3. blend models (zero or more joins; one per concept RIGHT AFTER the\n#                                  #      select list - the SQL-like spot)\n#   having  <result condition>     # 4. filter on an AGGREGATED / joined RESULT\n#   order by <col> asc|desc        # 5. sort\n#   limit   <n>                    # 6. cap rows\nimport enrollments as enroll;\nimport students as students;\n\n# --- TOP-LEVEL DEFINITIONS (reusable; all live ABOVE the query) -------------\n# An `auto`/`metric`/`property`/`key` defines a field. It expands inline wherever\n# referenced (a macro), re-evaluated in the referencing query's scope.\nauto completed_credits <- sum(enroll.credits ? enroll.completed = true);\n\n# A ROWSET is a NAMED select: `rowset <name> <- <a full select>;`. It runs as its\n# own scoped query (its own where/select/having) and exposes its outputs as\n# `<name>.<col>`. ALIAS every column you reuse downstream with `as`.\nrowset dept_totals <- select\n    enroll.department as department,\n    sum(enroll.credits) as total_credits,\n;\n\n# --- THE QUERY - clauses in the fixed order above ---------------------------\nwhere enroll.year >= 2015                   # 1. WHERE: per-row filter, before aggregation\nselect                                      # 2. SELECT: grouped automatically by students.major\n    students.major,\n    count(enroll.id) as enrollments,\n    --completed_credits,                    #    a leading `--` HIDES a column from the output\nsubset join enroll.student_id = students.id  # 3. JOIN: blend students onto enrollments (after the select list)\nhaving completed_credits > 0                # 4. HAVING: condition on an aggregated RESULT\norder by enrollments desc nulls first       # 5. ORDER BY\nlimit 100;                                  # 6. LIMIT\n\n# Reference a rowset's outputs as `<rowset>.<output>` in a later query.\nselect\n    dept_totals.department,\n    dept_totals.total_credits,\norder by dept_totals.total_credits desc nulls first\nlimit 100;\n\n# ---------------------------------------------------------------------------\n# NOTES:\n#  - Joins sit RIGHT AFTER the select list (the SQL-like, preferred spot). They\n#    may also appear before `select` - both parse - but keep them after the\n#    select list for consistency.\n#  - `where` filters INPUT rows (before aggregation). To filter on something only\n#    known AFTER the join / aggregation (e.g. comparing two joined rowsets'\n#    counts), select that value (hide it with `--`) and test it in `having` -\n#    `having` is the post-aggregation/output filter. There is only ONE `where`.\n#  - Output rows dedupe to the select grain. To keep legitimate duplicates (one\n#    row per matching fact), select the fact's grain keys - hide with `--` if\n#    they shouldn't appear in the output.\n#  - No FROM, GROUP BY, DISTINCT, SELECT *, subqueries, or SQL-style set/JOIN\n#    operators. Grouping is automatic; blend with the scoped `join` above.\n"
  },
  {
    "name": "rank-over-rollup",
    "title": "Rank within each rollup level (one window over the rollup)",
    "summary": "rank rollup subtotals/leaves with a SINGLE `rank(a,b) over (partition by level, parent ...)` - not separate ranks per level",
    "body": "# When ranking the rows of a ROLLUP within each hierarchy level, use ONE\n# multi-key window over the rollup output. `grouping()` gives the level; the\n# window partitions by (level, parent) so leaves rank within their parent and\n# subtotals rank among themselves - all in one pass. Do NOT write separate rank\n# concepts per level (they mis-rank across the wrong row set). The aggregates and\n# grouping() level concepts are plain - the select's `by rollup (…)` clause stamps\n# the grouping onto all of them.\nimport enrollments as enroll;\n\nauto total <- count(enroll.id);\nauto g_course <- grouping(enroll.course);\nauto g_year <- grouping(enroll.year);\nauto level <- g_course + g_year;   # 0 = leaf, 1 = course subtotal, 2 = grand total\nauto parent <- case when g_year = 0 then enroll.course else null end;\nauto rnk <- rank(enroll.course, enroll.year)\n    over (partition by level, parent order by total desc);\n\nselect\n    enroll.course,\n    enroll.year,\n    total,\n    level,\n    --parent,\n    rnk,\nby rollup (enroll.course, enroll.year)\norder by level desc nulls first, parent asc nulls first, rnk asc nulls first\nlimit 100;\n\n# ---------------------------------------------------------------------------\n# NOTE - a composite aggregate over a rollup (a difference/ratio of sums) needs\n# NO special handling: `sum(profit) - sum(loss) as net` rolls up both operands\n# to the same levels, because `by rollup (…)` is a property of the whole select,\n# not of one aggregate.\n"
  },
  {
    "name": "rollup",
    "title": "Subtotals + grand total in one pass with `by rollup (…)`",
    "summary": "subtotals and a grand total in one pass, and labeling the levels",
    "body": "# A `by rollup (d1, d2)` clause AFTER the select list (before having/order by)\n# computes the whole select at MULTIPLE grain levels in one pass - the grouping\n# sets (d1, d2), (d1), () - i.e. per-(d1,d2) leaf rows, a subtotal per d1, and a\n# grand total. (`by cube (d1, d2)` = every combination; `by rollup ()` over the\n# select's own grain.) It applies to EVERY aggregate in the select, so all\n# measures share one consistent grouping.\nimport enrollments as enroll;\n\n# `grouping(d)` = 1 when d is ROLLED UP on a row (a subtotal/grand-total row), 0 on\n# a leaf - use it to LABEL those rows: the rolled-up dimension is otherwise NULL\n# and would collide with any genuine NULL in the data.\nselect\n    case when grouping(enroll.department) = 1 then 'ALL DEPARTMENTS'\n         else enroll.department end as department,\n    case when grouping(enroll.course) = 1 then 'all courses'\n         else enroll.course end as course,\n    sum(enroll.credits) as total_credits\nby rollup (enroll.department, enroll.course)\nhaving total_credits > 0\norder by department asc nulls first, course asc nulls first\nlimit 100;\n\n# ---------------------------------------------------------------------------\n# NOTES:\n#  - CLAUSE ORDER matches SQL: the `by rollup (…)` grouping clause comes BEFORE\n#    `having` (select list -> by rollup -> having -> order by -> limit). The\n#    HAVING filters EVERY grouping level - subtotal and grand-total rows too.\n#  - SORT: use EXACTLY the sort the question asks for. Rollup rows are ordinary rows\n#    and sort with everything else (their rolled-up dimensions are NULL, hence\n#    `nulls first`/`nulls last` decides where they land). Sorting by LEVEL is OPTIONAL\n#    and only when you actually want leaves/subtotals/totals grouped together: ORDER BY\n#    cannot compute a fresh aggregate, so PROJECT the level (`grouping(a) + grouping(b)`)\n#    as a HIDDEN (`--`) column and sort by its alias:\n#        --grouping(enroll.department) + grouping(enroll.course) as _level\n#        order by _level asc, department asc nulls first\n#    Do NOT add `_level` to a sort the question already specified - a leading sort key\n#    changes WHICH rows survive a `limit`, so it can silently drop the totals.\n#  - COMPOSITE measures just work: `sum(a) - sum(b) as net` rolls up BOTH operands\n#    to the same levels because the `by rollup (…)` clause covers the whole select.\n#    To zero-fill a measure, wrap it: `coalesce(sum(a), 0) as a`.\n#  - FILTER-BEFORE-ROLLUP vs `having`: `by rollup (…) having x > t` filters EVERY level AFTER\n#    the rollup, so the subtotal/total rows still AGGREGATE the below-threshold leaves (they\n#    just aren't displayed). To keep only leaf groups meeting a threshold and roll up JUST\n#    those survivors, filter the leaves in a rowset FIRST (`rowset kept <- select … having x >\n#    t`), then `by rollup ()` over `kept`. `having` on the rollup itself is the wrong tool when\n#    subtotals must exclude the filtered-out leaves.\n"
  },
  {
    "name": "row-level-where-vs-having",
    "title": "Row-level filter (WHERE) vs aggregate filter (HAVING) - don't wrap a per-row threshold in max()/min()",
    "summary": "choosing between WHERE and HAVING for a threshold condition",
    "body": "# A non-aggregate, per-ROW condition belongs in WHERE - it filters the rows that\n# feed every aggregate, BEFORE grouping. HAVING is ONLY for filtering on an\n# aggregate RESULT. These are different operations; do not substitute one for the\n# other.\nimport iris as iris;\n\n# RIGHT - keep only large-sepal FLOWERS, then average their petals.\n# `sepal_length > 6.0` is a per-row test on a column -> WHERE.\nwhere iris.sepal_length > 6.0\nselect\n    iris.species,\n    avg(iris.petal_length) as avg_petal,\norder by iris.species asc;\n\n# WRONG - `having max(iris.sepal_length) by iris.species > 6.0` does NOT keep\n# large-sepal rows. It keeps whole SPECIES whose single largest flower exceeds\n# 6.0, then averages ALL of that species' flowers (small ones included). Wrapping\n# a per-row threshold in max()/min() in HAVING silently changes the meaning, and\n# AND-ing it with another filter (e.g. a rank cutoff) often yields 0 rows because\n# the two now select disjoint populations.\n#\n# Pick by what the condition is ABOUT:\n#   per-row value of a column   -> WHERE     `where x.amount > 10000`\n#   an aggregate's result       -> HAVING    `having total_amount > 10000`\n#                                             (select it, hide with `--`)\n#   aggregate just SOME rows    -> inline `?` `sum(x.amount ? x.amount > 10000)`\n#\n# An aggregate condition CAN go in WHERE as a pre-filter (`where count(x) > 0`);\n# it groups by the SELECT grain unless pinned with `by <grain>` (`by *` = a\n# whole-table total). SCOPE: a WHERE aggregate computes over ALL rows of the\n# model - the other WHERE predicates never narrow its input (HAVING, selected,\n# and inline-`?` aggregates DO see the filtered rows). `by` pins the groups,\n# never the input rows; for an aggregate over the filtered rows use `having`\n# or a `then where` stage.\n"
  },
  {
    "name": "scoped-join",
    "title": "Blend two models in one query with a scoped subset/union join",
    "summary": "blending a second fact model or rowset into one query",
    "body": "# A query-scoped `join` blends a second model into ONE select without editing the\n# model files (the query-local equivalent of `merge`). A join DECLARES how the\n# two keys' value domains relate - it never drops rows (rendering is always\n# row-preserving; restrict rows with explicit `is not null` filters):\n#   subset join a = b  -> declares a's values are contained in b's (a is the\n#                         narrow side, b superset, all values in a in b)\n#   union  join a = b  -> neither domain contains the other; the key coalesces\n#                         and unmatched rows from EITHER side are kept\n# Place the clause(s) RIGHT AFTER the `select` list (the SQL-like spot).\nimport enrollments as enroll;\nimport students as students;\n\n# (1) SINGLE-KEY blend: bring students onto enrollments by the shared student\n# key. Enrollment student ids are a SUBSET of all student ids, so declare that;\n# majors with no enrollments are preserved with a NULL count.\nselect\n    students.major,\n    count(enroll.id) as enrollments,\nsubset join enroll.student_id = students.id\norder by enrollments desc nulls first\nlimit 100;\n\n# ---------------------------------------------------------------------------\n# (2) MULTI-KEY blend - JOIN ON THE FULL GRAIN. When facts share a COMPOSITE\n# grain, write ONE join clause per key. `trilogy explore` shows each fact's grain\n# as `@<k1, k2>` (e.g. a sales/returns fact keyed `@<department, course>`);\n# matching only ONE key fans out and DOUBLE-COUNTS. Two rowsets, joined on both\n# of their shared keys:\nrowset completed_by <- where enroll.completed = true\n    select enroll.department as dept, enroll.course as course, count(enroll.id) as completed_cnt;\nrowset incomplete_by <- where enroll.completed = false\n    select enroll.department as dept, enroll.course as course, count(enroll.id) as incomplete_cnt;\nrowset null_completed <- where enroll.completed is null\n    select enroll.department as dept, enroll.course as course, count(enroll.id) as null_completed_cnt;\n\nselect\n    completed_by.dept,\n    completed_by.course,\n    completed_by.completed_cnt,\n    incomplete_by.incomplete_cnt,\n    null_completed.null_completed_cnt,\nunion join completed_by.dept = incomplete_by.dept = null_completed.dept\nunion join completed_by.course = incomplete_by.course = null_completed.course\norder by completed_by.dept asc nulls first\nlimit 100;\n\n# ---------------------------------------------------------------------------\n# (3) SELF-PAIR across two periods/sets (period-over-period) - a useful shape\n# for \"this year vs last year\": build one rowset per period (each aggregated to\n# the SAME keys), filter to restrict to output to one side or the other\n# in having clause.\n\nrowset y2020 <- where enroll.year = 2020 select enroll.department as dept, count(enroll.id) as cnt;\nrowset y2021 <- where enroll.year = 2021 select enroll.department as dept, count(enroll.id) as cnt;\n\nselect\n    y2020.dept,\n    y2020.cnt as cnt_2020,\n    y2021.cnt as cnt_2021,\n    y2021.cnt - y2020.cnt as yoy_diff,\nunion join y2020.dept = y2021.dept\nhaving y2021.cnt is not null\norder by yoy_diff desc nulls first\nlimit 100;\n\n# ---------------------------------------------------------------------------\n# (4) EXPRESSION join keys - a key may be ANY expression (arithmetic, an\n# aggregate, a window), not just a bare field. Here each year is matched to the\n# PRIOR year by joining on an OFFSET key (`prev_year.yr + 1`), so the prior\n# year's count lands on the current row without a self-merge. Only `=` equality\n# is supported (a key below comparison level - wrap a comparison in parens).\nrowset cur_year  <- select enroll.year as yr, count(enroll.id) as cnt;\nrowset prev_year <- select enroll.year as yr, count(enroll.id) as cnt;\n\nselect\n    cur_year.yr,\n    cur_year.cnt as this_year,\n    prev_year.cnt as prior_year,\nunion join cur_year.yr = prev_year.yr + 1\norder by cur_year.yr asc\nlimit 100;\n\n# NOTES:\n#  - JOIN ON THE FULL GRAIN: one `join` clause per key in the two facts' shared\n#    `@<...>` grain. Under-joining (one key of a multi-key grain) can cause\n#    duplication. Chain `= c` to also pull a base key into the join\n#    group so its properties stay reachable (`union join a.k = b.k = base.k`).\n#  - Stacked clauses of the SAME type can share one prefix via `and`:\n#    `union join a.k1 = b.k1 and a.k2 = b.k2` == two stacked `union join` clauses.\n#    `and` joins distinct KEY-EQUALITY groups (not filters); `= c` chains keys into\n#    ONE group - both compose: `union join a.k = b.k = base.k and a.k2 = b.k2`.\n#  - A join key may be ANY expression (a computed/offset key, an aggregate, a\n#    window), not only a bare field - see (4). Only `=` equality is supported.\n#  - Joins NEVER drop rows: for an intersection (rows present in BOTH sides),\n#    add explicit conditions - `where <side_a attr> is not null and <side_b\n#    attr> is not null`. A one-sided `is not null` keeps the other side's\n#    exclusive rows.\n#  - `left`/`full`/`inner`/`right`/`cross join` are NOT valid query-scoped joins\n#    (they error) - only `subset`/`union`. Map an old `left join a = b` to\n#    `subset join b = a` (swap operands) and `full join a = b` to\n#    `union join a = b`. A union key-group must be ALL union (can't mix with\n#    subset on the SAME key; `union join a = b = c` chains one union group);\n"
  },
  {
    "name": "set-intersect-difference",
    "title": "Set intersection / difference on a multi-column key (presence per group)",
    "summary": "count tuples present in / absent from other groups via per-group presence flags - the multi-column INTERSECT/EXCEPT idiom",
    "body": "# To intersect or difference rows on a MULTI-COLUMN key (the SQL INTERSECT /\n# EXCEPT of several columns), group by the full key tuple and build a presence\n# flag per set with `sum(case when <set> then 1 else 0 end)`. Grouping keeps\n# NULL key parts as their own group (correct INTERSECT/EXCEPT semantics).\n# (Avoid concatenating nullable fields into a single key: `||` over a NULL\n# yields NULL, and `concat()`/`concat_ws()` skip NULLs, which conflates\n# distinct tuples - tuple grouping handles NULL parts correctly.)\nimport enrollments as enroll;\n\n# Presence of each (student_id, course) tuple among completed vs open enrollments.\nauto in_completed <- sum(case when enroll.completed = true then 1 else 0 end)\n    by enroll.student_id, enroll.course;\nauto in_open <- sum(case when enroll.completed = false then 1 else 0 end)\n    by enroll.student_id, enroll.course;\n\nselect\n    # intersection: tuples appearing in BOTH sets\n    sum(case when in_completed > 0 and in_open > 0 then 1 else 0 end) as in_both,\n    # difference: tuples completed but never open (completed EXCEPT open)\n    sum(case when in_completed > 0 and in_open = 0 then 1 else 0 end) as completed_only,\n;\n"
  },
  {
    "name": "staged-membership",
    "title": "Stage a coarse-grain membership set, then filter a fine-grain query",
    "summary": "filtering a fine-grain query by a set computed at a coarser grain",
    "body": "# When a query filters on a condition computed at a COARSER grain (e.g. \"items\n# sold in all 3 channels\", \"courses offered in more than one year\"), compute that\n# membership set in its own `rowset` and filter the fine-grain query with `in`.\n# Staging keeps the coarse aggregate from entangling with the fine-grain\n# aggregates (which otherwise re-aggregate / over-count).\nimport enrollments as enroll;\n\n# Coarse stage: courses offered in more than one year.\nrowset multi_year <- select\n    enroll.course as course,\n    --count_distinct(enroll.year) as year_count,\nhaving year_count > 1\n;\n\n# Fine stage: enrollments per course, only for those courses.\nwhere enroll.course in multi_year.course\nselect\n    enroll.course,\n    count(enroll.id) as enrollments,\norder by enrollments desc\nlimit 100;\n"
  },
  {
    "name": "union-stack-channels",
    "title": "Stack rows from several sources/channels with the union(...) TVF",
    "summary": "stacking several sources/channels together as rows",
    "body": "# `union(...)` is a relational table-valued function: it STACKS the rows of TWO OR\n# MORE self-contained `select` arms, positionally (like SQL `UNION ALL`), into one\n# named result. Use it to combine CHANNELS / SOURCES / labeled populations - ONE\n# ARM PER SOURCE, to any amount. It\n# is a row STACK, NOT a key-join: arms are matched by COLUMN POSITION, so every arm\n# must project the same number of columns, in the same order and types, as the\n# trailing `-> (...)` output list.\nimport enrollments as enroll;\n\n# IMPORTANT: each arm is an INLINE, self-contained select written directly inside\n# the `union(...)` - you CANNOT pass the name of a previously-defined rowset as an\n# arm; put the full select logic (its own `where`, its own aggregation) in the arm.\n# The arms' i-th column maps to the i-th name in the `-> (...)` output list; the\n# surface names inside each arm need not match - only POSITION does. Each arm may\n# group by its own dims (here `course`), so an arm can emit MANY rows.\nwith by_channel as union(\n    (where enroll.department = 'Biology'\n     select\n        'Biology' as channel,\n        enroll.course as course,\n        count(enroll.id) as enrollments,\n    ),\n    (where enroll.department = 'Chemistry'\n     select\n        'Chemistry' as channel,\n        enroll.course as course,\n        count(enroll.id) as enrollments,\n    ),\n    (where enroll.department = 'Physics'\n     select\n        'Physics' as channel,\n        enroll.course as course,\n        count(enroll.id) as enrollments,\n    )\n) -> (channel, course, enrollments);\n\n# Reference the stacked outputs as `<rowset>.<output>`.\nselect\n    by_channel.channel,\n    by_channel.course,\n    by_channel.enrollments,\norder by by_channel.channel, by_channel.enrollments desc nulls first\nlimit 100;\n\n# ---------------------------------------------------------------------------\n# NOTES:\n#  - Pass TWO OR MORE arms - add a fourth/fifth the same way; one arm per source.\n#  - The trailing `-> (channel, course, enrollments)` NAMES the positional outputs;\n#    column order / count / type must line up across every arm.\n#  - Every union output is treated as a KEY (grain component). To RE-AGGREGATE the\n#    stack (e.g. a grand total across channels), wrap it in an outer aggregate:\n#        select sum(by_channel.enrollments) by rollup by_channel.channel as total;\n#  - An arm may carry its OWN query-scoped join (`select ... subset join b = a`\n#    after its select list) - localize each source's join to the arm that needs it.\n#  - This is NOT the forbidden SQL `UNION` keyword between two selects; it is the\n#    `union(...)` function form - the cleanest way to stack rows from several\n#    sources.\n#  - AGGREGATING across a union/set-op: an arm's `select` dedups to its own output\n#    grain BEFORE stacking (all selects are select distinct), \n#    so stacking raw per-row values (a measure, a `1` flag)\n#    and summing/counting OUTSIDE the union silently undercounts whenever two source\n#    rows in one arm project the same tuple (e.g. two same-priced sales in a week).\n#    Pre-aggregate INSIDE each arm (`sum(sales) as v`, `sum(1) as cnt` - as this\n#    example's `count(enroll.id)` does), or pull the arm's grain key through as an\n#    extra output column so every fact row stays distinct (downstream selects can\n#    just ignore it). And count a GUARANTEED-non-null key, never a nullable display\n#    column: `except`/`intersect` keep all-null rows (NULL-safe), which\n#    `count(nullable_col)` then silently skips.\n"
  },
  {
    "name": "window-period-over-period",
    "title": "Period-over-period ratio with a window function",
    "summary": "`lead`/`lag` over (order by ...) to compare a row to an offset period; build a scoped set with `<col> ? <cond>` and filter with `in`",
    "body": "# `<col> ? <cond>` builds a filtered set of values you can match with `in`.\n# lead()/lag() over (order by ...) compares each row to an offset row - here\n# each year's enrollment count divided by the PRIOR year's.\nimport enrollments as enroll;\n\nauto recent_years <- enroll.year ? enroll.year >= 2015;\n\ndef vs_prior_year(amt) -> round(amt / (lag(amt, 1) over (order by enroll.year asc)), 2);\n\nwhere enroll.year in recent_years\nselect\n    enroll.year,\n    @vs_prior_year(count(enroll.id)) as enrollment_growth,\nhaving\n    enrollment_growth is not null\norder by enroll.year asc nulls first;\n"
  }
]
